export function withTheme<T extends object>(value: T) {
    return {
        oneOf: [
            {
                ...value,
                optionName: 'no theme',
            },
            {
                type: 'object',
                additionalProperties: false,
                required: [Theme.Light],
                properties: Object.values(Theme).reduce(
                    (result, themeName) => ({
                        ...result,
                        [themeName]: value,
                    }),
                    {},
                ),
                optionName: 'themes',
            },
        ],
    };
}

export function withDevice<T extends object>(value: T) {
    return {
        oneOf: [
            {
                ...value,
                optionName: 'no device',
            },
            {
                type: 'object',
                additionalProperties: false,
                required: [Device.Desktop, Device.Mobile],
                properties: Object.values(Device).reduce(
                    (result, deviceName) => ({
                        ...result,
                        [deviceName]: value,
                    }),
                    {},
                ),
                optionName: 'devices',
            },
        ],
    };
}

